def best_chain(L):
    b = 0
    for mask in range(1 << L):
        s = [i for i in range(L) if mask >> i & 1]
        if all(s[j + 1] - s[j] != 1 for j in range(len(s) - 1)):
            b = max(b, len(s))
    return b
